const examples = [
  { date: "2026-10-20", context: "personal", currency: "NGN", kind: "income", category: "freelance", amount: 85000 },
  { date: "2026-10-20", context: "personal", currency: "NGN", kind: "expense", category: "groceries", amount: 6000 },
  { date: "2026-10-21", context: "personal", currency: "NGN", kind: "expense", category: "transport", amount: 4000 },
  { date: "2026-10-21", context: "business", currency: "NGN", kind: "income", category: "services", amount: 120000 },
  { date: "2026-10-21", context: "business", currency: "NGN", kind: "expense", category: "operations", amount: 20000 },
  { date: "2026-10-21", context: "personal", currency: "USD", kind: "income", category: "online work", amount: 10 }
];
// Artificial test records only; no real accounts or customer data.
return examples.map((row) => ({ json: row }));

const transactions = $input.all().map((item) => item.json);
const buckets = {};
for (const t of transactions) {
  if (!["personal", "business"].includes(t.context) ||
      !["NGN", "USD"].includes(t.currency) ||
      !["income", "expense"].includes(t.kind) ||
      !Number.isFinite(Number(t.amount)) || Number(t.amount) < 0) {
    throw new Error("Invalid demo transaction");
  }
  const key = t.context + ":" + t.currency;
  if (!buckets[key]) {
    buckets[key] = { context: t.context, currency: t.currency, income: 0, expenses: 0, transaction_count: 0 };
  }
  buckets[key][t.kind === "income" ? "income" : "expenses"] += Number(t.amount);
  buckets[key].transaction_count++;
}
const summaries = Object.values(buckets).map((s) => ({ ...s, net_cashflow: s.income - s.expenses }));
return summaries.map((s) => ({ json: s }));

const byCurrencyAndContext = $input.all().map((item) => item.json);
return [{
  json: {
    demo: true,
    source: "synthetic transactions embedded in the workflow",
    warning: "No exchange-rate conversion or production synchronization is performed",
    totals: byCurrencyAndContext,
    bucket_count: byCurrencyAndContext.length
  }
}];
